// ---- helpers ----
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

function resizeImage(file, maxW = 480) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement('canvas');
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.72));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

const fmtDate = (iso) => {
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = text.split(/\s+/);
  let line = '';
  let curY = y;
  for (let i = 0; i < words.length; i++) {
    const test = line ? line + ' ' + words[i] : words[i];
    if (ctx.measureText(test).width > maxWidth && line) {
      ctx.fillText(line, x, curY);
      line = words[i];
      curY += lineHeight;
    } else {
      line = test;
    }
  }
  if (line) {
    ctx.fillText(line, x, curY);
    curY += lineHeight;
  }
  return curY;
}

function roundRectPath(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

async function generateEntryImage(entry) {
  if (document.fonts && document.fonts.ready) {
    try { await document.fonts.ready; } catch {}
  }

  const W = 900;
  const pad = 48;
  let photoImg = null;
  if (entry.photo) {
    try { photoImg = await loadImage(entry.photo); } catch {}
  }
  const photoH = photoImg ? 420 : 0;

  const scratch = document.createElement('canvas');
  const sctx = scratch.getContext('2d');
  sctx.font = '15px "Source Sans 3", sans-serif';
  const contentW = W - pad * 2;
  const thirdsList = [
    ['First third', entry.thirds?.first, entry.thirdsFlavors?.first],
    ['Second third', entry.thirds?.second, entry.thirdsFlavors?.second],
    ['Final third', entry.thirds?.final, entry.thirdsFlavors?.final],
  ].filter(([, v]) => v);

  let estThirdsH = 0;
  thirdsList.forEach(([, text, flavors]) => {
    estThirdsH += 26;
    const words = text.split(/\s+/);
    let lines = 1, line = '';
    words.forEach((w) => {
      const test = line ? line + ' ' + w : w;
      if (sctx.measureText(test).width > contentW - 20) { lines++; line = w; } else { line = test; }
    });
    estThirdsH += lines * 22 + 18;
    if (flavors && flavors.length) estThirdsH += 22;
  });

  const headerH = 210;
  const H = pad + photoH + (photoImg ? 24 : 0) + headerH + (thirdsList.length ? estThirdsH + 40 : 0) + pad + 60;

  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');

  // background — deep tobacco leather with soft vignette
  const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
  bgGrad.addColorStop(0, '#241a11');
  bgGrad.addColorStop(1, '#170f09');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);
  const vignette = ctx.createRadialGradient(W / 2, 0, 40, W / 2, 0, W * 0.9);
  vignette.addColorStop(0, 'rgba(201,165,92,0.10)');
  vignette.addColorStop(1, 'rgba(201,165,92,0)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);

  let y = 0;

  if (photoImg) {
    const scale = Math.max(W / photoImg.width, photoH / photoImg.height);
    const dw = photoImg.width * scale;
    const dh = photoImg.height * scale;
    ctx.save();
    roundRectPath(ctx, 0, 0, W, photoH, 0);
    ctx.clip();
    ctx.drawImage(photoImg, (W - dw) / 2, (photoH - dh) / 2, dw, dh);
    const shade = ctx.createLinearGradient(0, photoH - 90, 0, photoH);
    shade.addColorStop(0, 'rgba(23,15,9,0)');
    shade.addColorStop(1, 'rgba(23,15,9,0.55)');
    ctx.fillStyle = shade;
    ctx.fillRect(0, photoH - 90, W, 90);
    ctx.restore();
    y = photoH + 40;
  } else {
    y = pad;
  }

  // brand
  ctx.fillStyle = '#f3e9d8';
  ctx.font = '600 40px Fraunces, serif';
  ctx.fillText(entry.brand, pad, y + 40);

  // name
  if (entry.name) {
    ctx.fillStyle = '#b3a082';
    ctx.font = 'italic 20px Fraunces, serif';
    ctx.fillText(entry.name, pad, y + 72);
  }

  // rating badge
  const badgeCx = W - pad - 44;
  const badgeCy = y + 40;
  const grad = ctx.createRadialGradient(badgeCx - 10, badgeCy - 12, 4, badgeCx, badgeCy, 44);
  grad.addColorStop(0, '#f6ecd9');
  grad.addColorStop(0.55, '#e7d4ad');
  grad.addColorStop(1, '#c9a55c');
  ctx.beginPath();
  ctx.arc(badgeCx, badgeCy, 44, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = '#9c7a3c';
  ctx.stroke();
  ctx.fillStyle = '#5c3a1e';
  ctx.font = '600 26px Fraunces, serif';
  ctx.textAlign = 'center';
  ctx.fillText(entry.rating.toFixed(1), badgeCx, badgeCy + 9);
  ctx.textAlign = 'left';

  y += 100;

  const metaParts = [entry.vitola, entry.price, entry.pairing, fmtDate(entry.date)].filter(Boolean);
  ctx.font = '500 15px "Source Sans 3", sans-serif';
  let mx = pad;
  metaParts.forEach((part) => {
    const textW = ctx.measureText(part).width;
    const chipW = textW + 24;
    ctx.fillStyle = '#2b1f14';
    ctx.strokeStyle = '#4a3826';
    roundRectPath(ctx, mx, y, chipW, 34, 17);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#e8dbc3';
    ctx.fillText(part, mx + 12, y + 22);
    mx += chipW + 10;
    if (mx > W - pad - 100) { mx = pad; y += 44; }
  });
  y += 56;

  if (thirdsList.length) {
    ctx.strokeStyle = '#4a3826';
    ctx.beginPath();
    ctx.moveTo(pad, y);
    ctx.lineTo(W - pad, y);
    ctx.stroke();
    y += 34;

    thirdsList.forEach(([label, text, flavors]) => {
      ctx.fillStyle = '#c9a55c';
      ctx.fillRect(pad, y - 16, 4, 20);
      ctx.fillStyle = '#e8dbc3';
      ctx.font = '600 17px "Source Sans 3", sans-serif';
      ctx.fillText(label, pad + 16, y);
      y += 26;
      ctx.fillStyle = '#c7b89c';
      ctx.font = '15px "Source Sans 3", sans-serif';
      y = wrapText(ctx, text, pad + 16, y, contentW - 20, 22);
      if (flavors && flavors.length) {
        ctx.fillStyle = '#c9a55c';
        ctx.font = 'italic 13px Fraunces, serif';
        ctx.fillText(flavors.join('  ·  '), pad + 16, y);
        y += 22;
      }
      y += 18;
    });
  }

  ctx.fillStyle = '#8a7a5f';
  ctx.font = 'italic 13px Fraunces, serif';
  ctx.fillText('True Herf Cigar Journal', pad, H - 24);

  return canvas.toDataURL('image/png');
}

// ---- splash screen ----

function SplashScreen() {
  const embers = [
    { left: '38%', delay: '0.3s', size: 6 },
    { left: '52%', delay: '0.6s', size: 4 },
    { left: '46%', delay: '0.9s', size: 5 },
    { left: '60%', delay: '0.4s', size: 3 },
  ];
  const wisps = [
    { left: '20%', size: 90, delay: '1.45s', drift: '-40px' },
    { left: '35%', size: 120, delay: '1.5s', drift: '-16px' },
    { left: '48%', size: 150, delay: '1.55s', drift: '10px' },
    { left: '58%', size: 110, delay: '1.6s', drift: '30px' },
    { left: '70%', size: 95, delay: '1.65s', drift: '48px' },
    { left: '28%', size: 130, delay: '1.7s', drift: '-30px' },
    { left: '52%', size: 160, delay: '1.75s', drift: '4px' },
    { left: '63%', size: 100, delay: '1.85s', drift: '38px' },
    { left: '40%', size: 140, delay: '1.9s', drift: '-22px' },
    { left: '18%', size: 105, delay: '1.95s', drift: '-52px' },
    { left: '75%', size: 90, delay: '2.0s', drift: '58px' },
    { left: '46%', size: 170, delay: '2.05s', drift: '0px' },
  ];
  return (
    <div className="splash-screen">
      <div className="splash-vignette" />
      <div className="smoke-sheet" />
      {embers.map((e, i) => (
        <div
          key={i}
          className="splash-ember"
          style={{ left: e.left, bottom: '48%', width: e.size, height: e.size, animationDelay: e.delay }}
        />
      ))}
      {wisps.map((w, i) => (
        <div
          key={i}
          className="smoke-wisp"
          style={{ left: w.left, width: w.size, height: w.size, animationDelay: w.delay, '--drift': w.drift }}
        />
      ))}
      <div className="flex flex-col items-center relative" style={{ zIndex: 2 }}>
        <div className="splash-band">
          <span
            className="font-serif font-semibold"
            style={{
              position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: '#5c3a1e', fontSize: 30, letterSpacing: '-0.02em',
            }}
          >
            TH
          </span>
        </div>
        <div className="splash-wordmark">
          <div className="splash-title">True Herf</div>
          <div className="splash-sub">Cigar Journal</div>
        </div>
      </div>
    </div>
  );
}

